import PackageDescription

let package = Package(
    name: "kvhttp",
    platforms: [.macOS(.v15)],
    targets: [
        .executableTarget(
            name: "KVHTTP"
        ),
    ]
)

import Darwin

/// Reasons a request could not be read off the wire.
enum RequestReadError: Error {
    /// The peer closed the connection before sending anything.
    case closedBeforeRequest
    case malformed
    case headersTooLarge
    case bodyTooLarge
    case unsupportedTransferEncoding
    case timedOut
    case io(errno: Int32)

    /// The response to send back, if the connection is still usable for one.
    var response: HTTPResponse? {
        switch self {
        case .closedBeforeRequest, .io: nil
        case .malformed: HTTPResponse(status: .badRequest)
        case .headersTooLarge: HTTPResponse(status: .headersTooLarge)
        case .bodyTooLarge: HTTPResponse(status: .payloadTooLarge)
        case .unsupportedTransferEncoding: HTTPResponse(status: .notImplemented)
        case .timedOut: HTTPResponse(status: .requestTimeout)
        }
    }
}

/// A blocking, single-request HTTP/1.1 connection over a connected socket.
struct Connection: ~Copyable {
    static let maxHeaderSize = 64 * 1024
    static let maxBodySize = 1 << 20
    private static let readChunkSize = 64 * 1024
    private static let headerTerminator: [UInt8] = Array("\r\n\r\n".utf8)

    private let fd: Int32

    init(fd: Int32) {
        self.fd = fd
    }

    deinit {
        // Half-close, then drain whatever the client still sends so the kernel
        // does not reset the connection and discard our response.
        Darwin.shutdown(fd, SHUT_WR)
        var scratch = [UInt8](repeating: 0, count: 4096)
        while scratch.withUnsafeMutableBytes({ recv(fd, $0.baseAddress, $0.count, 0) }) > 0 {}
        Darwin.close(fd)
    }

    func readRequest() throws(RequestReadError) -> HTTPRequest {
        var buffer: [UInt8] = []
        buffer.reserveCapacity(8 * 1024)

        var searchFrom = 0
        let headerEnd: Int
        while true {
            if let end = Self.find(Self.headerTerminator, in: buffer, from: searchFrom) {
                headerEnd = end
                break
            }
            guard buffer.count <= Self.maxHeaderSize else { throw .headersTooLarge }
            searchFrom = max(0, buffer.count - (Self.headerTerminator.count - 1))
            guard try receive(into: &buffer) > 0 else {
                throw buffer.isEmpty ? .closedBeforeRequest : .malformed
            }
        }

        var request = try Self.parseHead(buffer[..<headerEnd])
        let bodyStart = headerEnd + Self.headerTerminator.count
        let contentLength = try Self.contentLength(of: request)

        var body = Array(buffer[bodyStart...])
        guard body.count <= contentLength else { throw .malformed }
        body.reserveCapacity(contentLength)
        while body.count < contentLength {
            guard try receive(into: &body, limit: contentLength - body.count) > 0 else { throw .malformed }
        }
        request.body = body
        return request
    }

    func send(_ response: HTTPResponse) {
        var bytes = response.serializedHead()
        bytes.append(contentsOf: response.body)
        bytes.withUnsafeBytes { raw in
            var offset = 0
            while offset < raw.count {
                let sent = Darwin.send(fd, raw.baseAddress! + offset, raw.count - offset, 0)
                if sent > 0 {
                    offset += sent
                } else if sent < 0 && errno == EINTR {
                    continue
                } else {
                    return
                }
            }
        }
    }

    // MARK: - Reading

    /// Appends up to `limit` received bytes to `buffer`; returns the count (0 on EOF).
    private func receive(into buffer: inout [UInt8], limit: Int = readChunkSize) throws(RequestReadError) -> Int {
        let wanted = min(limit, Self.readChunkSize)
        let oldCount = buffer.count
        var received = 0
        var failure: Int32 = 0
        buffer.append(contentsOf: repeatElement(0, count: wanted))
        while true {
            received = buffer.withUnsafeMutableBytes { raw in
                recv(fd, raw.baseAddress! + oldCount, wanted, 0)
            }
            if received >= 0 { break }
            failure = errno
            if failure != EINTR { break }
        }
        buffer.removeLast(wanted - max(received, 0))
        if received < 0 {
            throw failure == EAGAIN || failure == EWOULDBLOCK ? .timedOut : .io(errno: failure)
        }
        return received
    }

    // MARK: - Parsing

    private static func parseHead(_ bytes: ArraySlice<UInt8>) throws(RequestReadError) -> HTTPRequest {
        let text = String(decoding: bytes, as: UTF8.self)
        var lines = text.split(separator: "\r\n", omittingEmptySubsequences: false)[...]
        guard let requestLine = lines.popFirst() else { throw .malformed }

        let parts = requestLine.split(separator: " ", omittingEmptySubsequences: false)
        guard parts.count == 3, !parts[0].isEmpty, parts[1].hasPrefix("/") || parts[1] == "*",
              parts[2].hasPrefix("HTTP/1.") else {
            throw .malformed
        }

        var headers: [(name: String, value: String)] = []
        for line in lines {
            guard let colon = line.firstIndex(of: ":") else { throw .malformed }
            let name = line[..<colon]
            guard !name.isEmpty, !name.contains(where: \.isWhitespace) else { throw .malformed }
            let value = line[line.index(after: colon)...].trimmingWhitespace()
            headers.append((name: String(name), value: String(value)))
        }

        return HTTPRequest(
            method: String(parts[0]),
            target: String(parts[1]),
            version: String(parts[2]),
            headers: headers,
            body: []
        )
    }

    private static func contentLength(of request: HTTPRequest) throws(RequestReadError) -> Int {
        if let encoding = request.header("Transfer-Encoding"), encoding.lowercased() != "identity" {
            throw .unsupportedTransferEncoding
        }
        let values = Set(request.headers.filter { $0.name.lowercased() == "content-length" }.map(\.value))
        guard let value = values.first else { return 0 }
        guard values.count == 1, !value.isEmpty, value.utf8.allSatisfy({ (0x30...0x39).contains($0) }) else {
            throw .malformed
        }
        guard value.utf8.count <= 10, let length = Int(value), length <= maxBodySize else {
            throw .bodyTooLarge
        }
        return length
    }

    private static func find(_ needle: [UInt8], in haystack: [UInt8], from start: Int) -> Int? {
        guard haystack.count >= needle.count, start <= haystack.count - needle.count else { return nil }
        for index in start...(haystack.count - needle.count)
        where haystack[index] == needle[0] && haystack[index..<(index + needle.count)].elementsEqual(needle) {
            return index
        }
        return nil
    }
}

private extension Substring {
    func trimmingWhitespace() -> Substring {
        let isSpace: (Character) -> Bool = { $0 == " " || $0 == "\t" }
        guard let first = firstIndex(where: { !isSpace($0) }) else { return "" }
        let last = lastIndex(where: { !isSpace($0) })!
        return self[first...last]
    }
}

/// A parsed HTTP request with its complete body.
struct HTTPRequest: Sendable {
    var method: String
    var target: String
    var version: String
    var headers: [(name: String, value: String)]
    var body: [UInt8]

    /// Path component of the request target, without any query string.
    var path: Substring {
        target.split(separator: "?", maxSplits: 1, omittingEmptySubsequences: false).first ?? ""
    }

    func header(_ name: String) -> String? {
        headers.first { $0.name.lowercased() == name.lowercased() }?.value
    }
}

struct HTTPStatus: Sendable, Equatable {
    let code: Int
    let reason: String

    static let ok = HTTPStatus(code: 200, reason: "OK")
    static let created = HTTPStatus(code: 201, reason: "Created")
    static let noContent = HTTPStatus(code: 204, reason: "No Content")
    static let badRequest = HTTPStatus(code: 400, reason: "Bad Request")
    static let notFound = HTTPStatus(code: 404, reason: "Not Found")
    static let methodNotAllowed = HTTPStatus(code: 405, reason: "Method Not Allowed")
    static let requestTimeout = HTTPStatus(code: 408, reason: "Request Timeout")
    static let payloadTooLarge = HTTPStatus(code: 413, reason: "Content Too Large")
    static let headersTooLarge = HTTPStatus(code: 431, reason: "Request Header Fields Too Large")
    static let notImplemented = HTTPStatus(code: 501, reason: "Not Implemented")
}

struct HTTPResponse: Sendable {
    var status: HTTPStatus
    var headers: [(name: String, value: String)] = []
    var body: [UInt8] = []

    init(status: HTTPStatus, contentType: String? = nil, body: [UInt8] = []) {
        self.status = status
        self.body = body
        if let contentType {
            headers.append((name: "Content-Type", value: contentType))
        }
    }

    init(status: HTTPStatus, text: String) {
        self.init(status: status, contentType: "text/plain; charset=utf-8", body: Array(text.utf8))
    }

    /// Wire representation of the status line and headers, terminated by an empty line.
    /// The connection is always closed after the response, so we announce it.
    func serializedHead() -> [UInt8] {
        var head = "HTTP/1.1 \(status.code) \(status.reason)\r\n"
        for (name, value) in headers {
            head += "\(name): \(value)\r\n"
        }
        head += "Content-Length: \(body.count)\r\n"
        head += "Connection: close\r\n\r\n"
        return Array(head.utf8)
    }
}

import Synchronization

/// Thread-safe in-memory key-value storage shared by all connections.
final class KeyValueStore: Sendable {
    enum PutOutcome: Sendable {
        case created
        case replaced
    }

    private let storage = Mutex<[String: [UInt8]]>([:])

    func get(_ key: String) -> [UInt8]? {
        storage.withLock { $0[key] }
    }

    @discardableResult
    func put(_ key: String, value: [UInt8]) -> PutOutcome {
        storage.withLock { $0.updateValue(value, forKey: key) == nil ? .created : .replaced }
    }

    /// Returns `true` if a value was removed.
    @discardableResult
    func delete(_ key: String) -> Bool {
        storage.withLock { $0.removeValue(forKey: key) != nil }
    }

    /// All keys, sorted ascending by byte value.
    func sortedKeys() -> [String] {
        let keys = storage.withLock { Array($0.keys) }
        return keys.sorted { $0.utf8.lexicographicallyPrecedes($1.utf8) }
    }
}

/// Maps requests onto store operations. Contains no I/O.
struct Router: Sendable {
    static let maxKeyLength = 64

    let store: KeyValueStore

    func handle(_ request: HTTPRequest) -> HTTPResponse {
        let path = request.path
        let method = request.method

        switch path {
        case "/health":
            guard method == "GET" else { return HTTPResponse(status: .methodNotAllowed) }
            return HTTPResponse(status: .ok, text: "ok")

        case "/kv":
            guard method == "GET" else { return HTTPResponse(status: .methodNotAllowed) }
            return listKeys()

        case let p where p.hasPrefix("/kv/"):
            let key = String(p.dropFirst("/kv/".count))
            guard Self.isValidKey(key) else { return HTTPResponse(status: .badRequest) }
            return handleKey(method: method, key: key, body: request.body)

        default:
            return HTTPResponse(status: .notFound)
        }
    }

    /// A key matches `[A-Za-z0-9_-]{1,64}`.
    static func isValidKey(_ key: String) -> Bool {
        let bytes = key.utf8
        guard (1...maxKeyLength).contains(bytes.count) else { return false }
        return bytes.allSatisfy { byte in
            switch byte {
            case UInt8(ascii: "A")...UInt8(ascii: "Z"),
                 UInt8(ascii: "a")...UInt8(ascii: "z"),
                 UInt8(ascii: "0")...UInt8(ascii: "9"),
                 UInt8(ascii: "_"), UInt8(ascii: "-"):
                true
            default:
                false
            }
        }
    }

    private func handleKey(method: String, key: String, body: [UInt8]) -> HTTPResponse {
        switch method {
        case "GET":
            guard let value = store.get(key) else { return HTTPResponse(status: .notFound) }
            return HTTPResponse(status: .ok, contentType: "application/octet-stream", body: value)

        case "PUT":
            switch store.put(key, value: body) {
            case .created: return HTTPResponse(status: .created)
            case .replaced: return HTTPResponse(status: .ok)
            }

        case "DELETE":
            return HTTPResponse(status: store.delete(key) ? .noContent : .notFound)

        default:
            return HTTPResponse(status: .methodNotAllowed)
        }
    }

    private func listKeys() -> HTTPResponse {
        // Valid keys never contain characters that need JSON escaping.
        let json = "[" + store.sortedKeys().map { "\"\($0)\"" }.joined(separator: ",") + "]"
        return HTTPResponse(status: .ok, contentType: "application/json", body: Array(json.utf8))
    }
}

import Darwin
import Foundation

struct ServerError: Error, CustomStringConvertible {
    let operation: String
    let code: Int32

    var description: String { "\(operation) failed: \(String(cString: strerror(code)))" }
}

/// A thread-per-connection HTTP server bound to the loopback interface.
final class Server: Sendable {
    private static let ioTimeoutSeconds = 10

    private let router: Router
    private let listener: Int32

    init(port: UInt16, router: Router) throws(ServerError) {
        self.router = router

        let fd = socket(AF_INET, SOCK_STREAM, 0)
        guard fd >= 0 else { throw ServerError(operation: "socket", code: errno) }

        var enable: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &enable, socklen_t(MemoryLayout<Int32>.size))

        var address = sockaddr_in()
        address.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
        address.sin_family = sa_family_t(AF_INET)
        address.sin_port = port.bigEndian
        address.sin_addr.s_addr = inet_addr("127.0.0.1")

        let bound = withUnsafePointer(to: &address) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
        guard bound == 0 else {
            let code = errno
            close(fd)
            throw ServerError(operation: "bind", code: code)
        }
        guard listen(fd, SOMAXCONN) == 0 else {
            let code = errno
            close(fd)
            throw ServerError(operation: "listen", code: code)
        }
        listener = fd
    }

    /// Accepts connections forever, serving each on its own thread.
    func run() -> Never {
        while true {
            let client = accept(listener, nil, nil)
            guard client >= 0 else { continue }
            configure(client: client)
            Thread.detachNewThread { [self] in
                serve(client)
            }
        }
    }

    private func configure(client fd: Int32) {
        var enable: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &enable, socklen_t(MemoryLayout<Int32>.size))
        var timeout = timeval(tv_sec: Self.ioTimeoutSeconds, tv_usec: 0)
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
        setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
    }

    private func serve(_ fd: Int32) {
        let connection = Connection(fd: fd)
        do {
            let request = try connection.readRequest()
            connection.send(router.handle(request))
        } catch {
            if let response = error.response {
                connection.send(response)
            }
        }
    }
}

import Darwin

func fail(_ message: String) -> Never {
    fputs("kvhttp: \(message)\n", stderr)
    exit(2)
}

signal(SIGPIPE, SIG_IGN)

let arguments = CommandLine.arguments
guard arguments.count == 2, let port = UInt16(arguments[1]), port > 0 else {
    fail("usage: \(arguments.first ?? "app") <port>")
}

do {
    let server = try Server(port: port, router: Router(store: KeyValueStore()))
    server.run()
} catch {
    fail(error.description)
}
